export function linksFor(id){return relations.flatMap(r=>r.from===id?[{id:r.to,label:r.forward,kind:r.kind}]:r.to===id?[{id:r.from,label:r.backward,kind:r.kind}]:[]);}
export function visibleCompositions(count){const limit=[4,8,12].includes(count)?count:8;return compositions.slice(0,limit/4);}
